22	    const reportedWarningRef = useRef('');
23	
24	    useEffect(() => {
25	        if (!snapshot.error || reportedErrorRef.current === snapshot.error) return;
26	        reportedErrorRef.current = snapshot.error;
27	        dialogService.error(snapshot.error, { fallbackMessage: 'Project stats could not be loaded' });
28	    }, [snapshot.error]);
29	
