54	        ? 'grouped'
55	        : controls.dataset === 'activityOverTime' && controls.activityMetric === 'actions' ? 'stacked' : 'single';
56	    const exclusions = Object.entries(snapshot.exclusionCounts) as Array<[StatsExclusionReason, number]>;
